
.sm-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(96px, 1fr));
  gap: 8px;
}

.sm-metric {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 6px 9px;
  border: 1px solid var(--c-border-soft);
  border-radius: var(--r-inner);
  background: var(--c-surface-alt);
}

.k {
  color: var(--c-text-dim);
  font-size: 11px;
}

.v {
  color: var(--c-text);
  font-size: 15px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.is-money .v {
  color: var(--c-money);
}

.is-channel .v {
  color: var(--c-channel);
}

.is-risk .v {
  color: var(--c-danger);
}
