
.sm-theme {
  position: relative;
}

.sm-theme-btn {
  padding: 2px 8px;
  border: 1px solid var(--c-border);
  border-radius: var(--r-inner, 3px);
  background: none;
  color: var(--c-text-muted);
  font-family: inherit;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  cursor: pointer;
  user-select: none;
}

.sm-theme-btn:hover {
  border-color: var(--c-accent);
  color: var(--c-accent);
}

.sm-theme-menu {
  position: absolute;
  top: calc(100% + 5px);
  right: 0;
  z-index: 20;
  min-width: 136px;
  margin: 0;
  padding: 3px;
  list-style: none;
  border: 1px solid var(--c-border);
  border-radius: var(--r-card);
  background: var(--c-surface);
  box-shadow: 0 8px 24px rgb(0 0 0 / 45%);
}

.sm-theme-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 7px;
  border-radius: 4px;
  color: var(--c-text-muted);
  font-size: 11px;
  cursor: pointer;
  user-select: none;
}

.sm-theme-item:hover {
  background: var(--c-surface-alt);
  color: var(--c-text);
}

.sm-theme-item.is-on {
  color: var(--c-accent);
  font-weight: 700;
}

.key {
  width: 10px;
  color: var(--c-text-dim);
  font-weight: 800;
}

.sm-theme-item.is-on .key {
  color: var(--c-accent);
}

.name {
  flex: 1;
}

.tick {
  width: 9px;
}
