
.sm-sec {
  padding: 9px 12px;
  border-bottom: 1px solid var(--c-border-soft);
}

.sm-sec:last-child {
  border-bottom: none;
}

.sm-cap {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0 0 6px;
  color: var(--c-text-dim);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.1em;
}

.sm-cap i {
  opacity: 0.85;
}
