
.sm-card {
  overflow: hidden;
  border: 1px solid var(--c-border);
  border-radius: var(--r-card);
  background: var(--c-surface);
}

.career {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 7px 12px;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface-alt);
  color: var(--c-text-muted);
  font-size: 12px;
}

.career i {
  color: var(--c-accent);
  font-size: 11px;
}

.career-stage {
  color: var(--c-accent);
  font-weight: 700;
}

.career-event {
  margin-left: auto;
  overflow: hidden;
  color: var(--c-text-dim);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.risk-bar {
  overflow: hidden;
  height: 4px;
  margin-top: 8px;
  border-radius: var(--r-inner);
  background: var(--c-track);
}

.risk-bar .fill {
  display: block;
  height: 100%;
  background: var(--c-tier-1);
  transition: width 0.4s ease;
}

.risk-bar .fill.is-hot {
  background: var(--c-danger);
}

.more {
  margin: 8px 0 0;
  color: var(--c-text-dim);
  font-size: 11px;
  text-align: center;
}
