
.sm-woman {
  padding: 10px 12px;
  border: 1px solid var(--c-border-soft);
  border-left: 3px solid var(--c-tier-0);
  border-radius: var(--r-card);
  background: var(--c-surface-alt);
}

.sm-woman + .sm-woman {
  margin-top: 8px;
}

.sm-woman.is-active {
  box-shadow: inset 0 0 0 1px var(--c-accent);
}

.sm-woman.t0 {
  border-left-color: var(--c-tier-0);
}
.sm-woman.t1 {
  border-left-color: var(--c-tier-1);
}
.sm-woman.t2 {
  border-left-color: var(--c-tier-2);
}
.sm-woman.t3 {
  border-left-color: var(--c-tier-3);
}

.head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  cursor: pointer;
  user-select: none;
}

.name {
  font-size: 15px;
  font-weight: 700;
}

.t0 .name {
  color: var(--c-tier-0);
}
.t1 .name {
  color: var(--c-tier-1);
}
.t2 .name {
  color: var(--c-tier-2);
}
.t3 .name {
  color: var(--c-tier-3);
}

.badge {
  padding: 1px 7px;
  border: 1px solid currentcolor;
  border-radius: 9px;
  font-size: 11px;
}

.t0 .badge {
  color: var(--c-tier-0);
}
.t1 .badge {
  color: var(--c-tier-1);
}
.t2 .badge {
  color: var(--c-tier-2);
}
.t3 .badge {
  color: var(--c-tier-3);
}

.tags {
  margin-left: auto;
  color: var(--c-text-muted);
  font-size: 12px;
}

.arrow {
  color: var(--c-text-dim);
  font-size: 10px;
  transition: transform 0.25s;
}

.arrow.is-open {
  transform: rotate(180deg);
}

.bars {
  margin-top: 8px;
  display: grid;
  gap: 5px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  flex: 0 0 28px;
  color: var(--c-text-dim);
  font-size: 11px;
}

.sm-bar {
  flex: 1;
  overflow: hidden;
  height: var(--bar-h);
  border-radius: var(--r-inner);
  background: var(--c-track);
}

.fill {
  display: block;
  height: 100%;
  transition: width 0.4s ease;
}

.fill.like {
  background: var(--c-tier-2);
}

.fill.trust {
  background: var(--c-channel);
}

.bar-num {
  flex: 0 0 26px;
  color: var(--c-text-dim);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.meta {
  margin-top: 5px;
  color: var(--c-text-dim);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.detail {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-border);
}

.drow {
  display: flex;
  gap: 9px;
  font-size: 12px;
  line-height: 1.55;
}

.drow + .drow {
  margin-top: 3px;
}

.drow dt {
  flex: 0 0 36px;
  color: var(--c-text-dim);
  white-space: nowrap;
}

.drow dd {
  flex: 1;
  margin: 0;
  color: var(--c-text-muted);
}
